function cleanEnv(name, fallback=''){
  const raw=process.env[name];
  if(raw===undefined||raw===null)return fallback;
  let v=String(raw).trim();
  if((v.startsWith('\"')&&v.endsWith('\"'))||(v.startsWith("'")&&v.endsWith("'")))v=v.slice(1,-1).trim();
  return v;
}
