  const safe=['public_profile','ads_read','ads_management','business_management','pages_show_list','pages_read_engagement'];
  const requested=splitScopes(cleanEnv('META_SCOPES'), safe);
  const extras=splitScopes(cleanEnv('META_EXTRA_SCOPES'), []);
  const blocked=new Set(['email','instagram_basic','instagram_manage_insights','leads_retrieval']);
  const allowBlocked=cleanEnv('META_ALLOW_UNREVIEWED_SCOPES','false').toLowerCase()==='true';
  return [...new Set([...requested,...extras].filter(x=>allowBlocked||!blocked.has(x)))];
