async function processTask(c,t){t.attempts=Number(t.attempts||0)+1;t.status='RUNNING';t.started_at=new Date().toISOString();t.last_error=null;markCoreDirty();persistCore(true);try{if(t.type==='sync_connector')t.result=await integratedSync(c,t.payload.connector);else if(t.type==='follow_up'){const rec={id:id(),type:'follow_up',status:'OPEN',message:t.payload?.message||t.title,created_at:new Date().toISOString()};upsertRecord(c,'crm',rec);t.result={created:true,record_id:rec.id}}else throw new Error('Onbekend taaktype');t.status='SUCCEEDED';t.completed_at=new Date().toISOString();t.next_attempt_at=null}catch(e){t.last_error=redactJarvisText(e.message||e,500);const max=Number(t.max_attempts||5);if(t.attempts>=max){t.status='DEAD_LETTER';t.next_attempt_at=null}else{t.status='RETRY_SCHEDULED';t.next_attempt_at=new Date(Date.now()+Math.min(3600000,30000*(2**(t.attempts-1)))).toISOString()}}markCoreDirty();persistCore(true);return t}
let workerRunning=false;
async function workerTick(c=trustedContext()){
  if(workerRunning)return {ok:false,status:'SKIPPED_OVERLAP',processed:[],auto_sync:[]};
  workerRunning=true;const started=new Date().toISOString();workerState.set('worker',{status:'RUNNING',started_at:started,pid:process.pid,host:os.hostname()});markCoreDirty();persistCore(true);
  try{
    const q=arr(tasks,key(c,'queue')),now=Date.now(),processed=[];for(const t of q.filter(x=>['QUEUED','RETRY_SCHEDULED'].includes(x.status)&&Date.parse(x.next_attempt_at||0)<=now).slice(0,10))processed.push(await processTask(c,t));
    const status=await universalStatuses(c,false),auto=[];for(const x of status.list.filter(x=>x.connected)){const last=Number(workerState.get(`${key(c,'lastsync')}:${x.id}`)||0);if(Date.now()-last<15*60*1000)continue;const spec=CONNECTOR_REGISTRY[x.id]||{},profile=CONNECTOR_RUNTIME.profiles()[x.id]||{};if(!(spec.capabilities||[]).includes('sync'))continue;const dedicated=['meta','instagram','facebook_pages','linkedin','tiktok','wix','google_ads','ga4','search_console','google_calendar'].includes(x.id);if(!dedicated&&!profile.sync?.path)continue;if(auto.length>=3)break;try{auto.push(await integratedSync(c,x.id))}catch(e){auto.push({ok:false,id:x.id,error:redactJarvisText(e.message,500)})}}
    const completed=new Date().toISOString();workerState.set('worker',{status:'IDLE',started_at:started,last_completed_at:completed,processed:processed.length,synced:auto.filter(x=>x.ok).length});markCoreDirty();addEvent(c,'worker','Autonome worker tick voltooid',{processed:processed.length,synced:auto.filter(x=>x.ok).length});persistCore(true);return {ok:true,status:'SUCCEEDED',processed,auto_sync:auto,completed_at:completed};
  }catch(e){
    const failedAt=new Date().toISOString(),message=redactJarvisText(e.message||e,500);workerState.set('worker',{status:'ERROR',started_at:started,last_failed_at:failedAt,last_error:message,pid:process.pid,host:os.hostname()});markCoreDirty();addEvent(c,'worker','Autonome worker tick mislukt',{error:message});persistCore(true);throw e;
  }finally{workerRunning=false}
}

async function bootstrapProvider(c,pid){
  let ingested=0;const warnings=[];
  if(pid==='meta'){
    const saved=loadConnector(c,'meta');if(!saved?.access_token)return {ok:false,provider:'meta',ingested:0,warnings:['Geen Meta access token']};const v=metaVersion(),token=saved.access_token;
    const [ads,pages]=await Promise.allSettled([metaGet(`https://graph.facebook.com/${v}/me/adaccounts?fields=id,name,account_status,currency,timezone_name&limit=100`,token),metaGet(`https://graph.facebook.com/${v}/me/accounts?fields=id,name,category,instagram_business_account&limit=100`,token)]);
    const adRows=ads.status==='fulfilled'?(ads.value.data||[]):[];const pageRows=pages.status==='fulfilled'?(pages.value.data||[]):[];
    if(ads.status==='rejected')warnings.push('Meta adaccounts: '+redactJarvisText(ads.reason?.message,500));if(pages.status==='rejected')warnings.push('Meta pages: '+redactJarvisText(pages.reason?.message,500));
    for(const x of adRows){upsertRecord(c,'social_media',{_source:'meta_ad_account',_ingested_at:new Date().toISOString(),...x});ingested++}
    for(const x of pageRows){upsertRecord(c,'social_media',{_source:'facebook_page',_ingested_at:new Date().toISOString(),...x});ingested++}
    for(const ad of adRows.slice(0,10)){
      const adid=encodeURIComponent(ad.id);const [campaigns,insights]=await Promise.allSettled([
        metaGet(`https://graph.facebook.com/${v}/${adid}/campaigns?fields=id,name,status,effective_status,objective,buying_type,created_time,updated_time&limit=100`,token),
        metaGet(`https://graph.facebook.com/${v}/${adid}/insights?fields=impressions,clicks,spend,reach,cpc,cpm,ctr,actions&date_preset=last_30d&level=account`,token)
      ]);
      if(campaigns.status==='fulfilled')for(const row of campaigns.value.data||[]){upsertRecord(c,'social_media',{_source:'meta_campaign',_ingested_at:new Date().toISOString(),ad_account_id:ad.id,...row});ingested++}else warnings.push(`${ad.name||ad.id} campaigns: ${redactJarvisText(campaigns.reason?.message,500)}`);
      if(insights.status==='fulfilled'){upsertRecord(c,'rapportages',{_source:'meta_account_insights',_ingested_at:new Date().toISOString(),id:`${ad.id}:last_30d`,ad_account_id:ad.id,period:'last_30d',data:insights.value.data||[]});ingested++}else warnings.push(`${ad.name||ad.id} insights: ${redactJarvisText(insights.reason?.message,500)}`);
    }
    const probe=await probeMeta(c,true);addEvent(c,'integration','Meta gekoppeld en live data ingeladen',{ingested,ad_accounts:probe.ad_accounts,pages:probe.pages,instagram:probe.services.instagram,warnings:warnings.length});return {ok:Boolean(probe.connected),provider:'meta',ingested,warnings,status:probe}
  }
  if(pid==='linkedin'){const p=await probeLinkedIn(c,true);if(p.connected){upsertRecord(c,'social_media',{_source:'linkedin_account',_ingested_at:new Date().toISOString(),id:p.account?.sub||p.account?.id||'me',account:p.account});ingested=1}addEvent(c,'integration','LinkedIn gekoppeld',{connected:p.connected});return {ok:p.connected,provider:pid,ingested,status:p}}
  if(pid==='tiktok'){const p=await probeTikTok(c,true);if(p.connected){upsertRecord(c,'social_media',{_source:'tiktok_account',_ingested_at:new Date().toISOString(),id:p.account?.open_id||'me',account:p.account});ingested=1}addEvent(c,'integration','TikTok gekoppeld',{connected:p.connected});return {ok:p.connected,provider:pid,ingested,status:p}}
  return {ok:false,provider:pid,ingested,warnings:['Onbekende provider']}
}
