  if(want.has('ga4')&&gs.services.ga4&&cleanEnv('GA4_PROPERTY_ID'))try{const prop=cleanEnv('GA4_PROPERTY_ID').replace(/^properties\//,'');const payload={dateRanges:[{startDate:'28daysAgo',endDate:'today'}],dimensions:[{name:'sessionDefaultChannelGroup'}],metrics:[{name:'sessions'},{name:'conversions'},{name:'totalUsers'}],limit:'100'};const d=await gfetch(c,`https://analyticsdata.googleapis.com/v1beta/properties/${prop}:runReport`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});upsertRecord(c,'rapportages',{_source:'ga4_bootstrap',_ingested_at:new Date().toISOString(),id:`${prop}:28d`,property_id:prop,report:d});ingested++}catch(e){warnings.push('GA4: '+redactJarvisText(e.message,500))}
