function adminPassword(){return env('FOUNDLY_ADMIN_PASSWORD')}
function adminToken(){return env('FOUNDLY_ADMIN_TOKEN')}
function authConfigured(){return Boolean(adminPassword()||adminToken())}
function authorized(req){if(env('NODE_ENV')!=='production'&&!authConfigured())return true;const bearer=String(req.headers.authorization||''),token=adminToken(),password=adminPassword();if(token&&bearer.startsWith('Bearer ')&&timingEqual(bearer.slice(7),token))return true;if(password&&bearer.startsWith('Basic ')){try{const [user,...rest]=Buffer.from(bearer.slice(6),'base64').toString('utf8').split(':');return timingEqual(user,env('FOUNDLY_ADMIN_USERNAME','foundly'))&&timingEqual(rest.join(':'),password)}catch{return false}}return false}
function authRuntimeDiagnostics(req){const has=name=>Object.prototype.hasOwnProperty.call(process.env,name),authorization=String(req.headers.authorization||''),match=authorization.match(/^([^ ]+)\s+(.+)$/),scheme=match?match[1].toLowerCase():'none',payload=match?.[2]||'';let basicPayloadSyntax=false;if(scheme==='basic'&&/^[A-Za-z0-9+/]+={0,2}$/.test(payload))try{basicPayloadSyntax=Buffer.from(payload,'base64').toString('utf8').includes(':')}catch{}return {configured:authConfigured(),basic_enabled:Boolean(adminPassword()),bearer_enabled:Boolean(adminToken()),username_env_present:has('FOUNDLY_ADMIN_USERNAME'),username_normalized_present:Boolean(env('FOUNDLY_ADMIN_USERNAME')),password_env_present:has('FOUNDLY_ADMIN_PASSWORD'),password_normalized_present:Boolean(adminPassword()),token_env_present:has('FOUNDLY_ADMIN_TOKEN'),token_normalized_present:Boolean(adminToken()),normalization:'trim_and_remove_one_matching_outer_quote_pair',comparison:'timing_safe_exact',request_authorization_present:Boolean(authorization),request_authorization_scheme:['basic','bearer'].includes(scheme)?scheme:(authorization?'other':'none'),request_basic_payload_syntax:basicPayloadSyntax,request_credentials_match:authorization?authorized(req):null}}
function isOAuthCallbackRoute(pathname){return /^\/api\/(?:connect\/(?:meta|linkedin|tiktok|wix)\/callback|google\/oauth\/callback|connector-runtime\/oauth\/[^/]+\/callback)$/.test(pathname)}
function isPublicRoute(pathname){return pathname==='/api/health'||pathname==='/api/ready'||pathname==='/api/diagnostics/runtime-auth'||isOAuthCallbackRoute(pathname)||/^\/api\/webhook\/(?:meta|whatsapp)$/.test(pathname)}
const rateBuckets=new Map();
function rateAllowed(req){const ip=String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'unknown').split(',')[0].trim(),now=Date.now(),key=`${ip}:${Math.floor(now/60000)}`,n=(rateBuckets.get(key)||0)+1;rateBuckets.set(key,n);if(rateBuckets.size>5000)for(const k of rateBuckets.keys())if(!k.endsWith(String(Math.floor(now/60000))))rateBuckets.delete(k);return n<=Number(env('FOUNDLY_RATE_LIMIT_PER_MINUTE','240'))}
function storageStatus(){const expected=DATA==='/data'||DATA.startsWith('/data/');let writable=false,separate_mount=false,free_bytes=null,error=null;try{const probe=path.join(DATA,'.foundly-readiness');fs.writeFileSync(probe,`ok:${Date.now()}`,{mode:0o600});writable=fs.readFileSync(probe,'utf8').startsWith('ok:');fs.unlinkSync(probe);separate_mount=fs.statSync(DATA).dev!==fs.statSync('/').dev;if(fs.statfsSync){const s=fs.statfsSync(DATA);free_bytes=Number(s.bavail)*Number(s.bsize)}}catch(e){error=redactJarvisText(e.message,500)}return {configured_path:expected,writable,separate_mount,free_bytes,error}}
const server=http.createServer(async(req,res)=>{const u=new URL(req.url,`http://${req.headers.host||'localhost'}`);try{if(!rateAllowed(req))return json(res,429,{error:'Te veel verzoeken'});if(isOAuthCallbackRoute(u.pathname)){if(req.method!=='GET')return json(res,405,{error:'Method not allowed'});const handled=await api(req,res,u);if(handled!==false)return;return json(res,404,{error:'OAuth callbackroute niet gevonden'})}if(!isPublicRoute(u.pathname)&&!authorized(req)){res.writeHead(401,baseHeaders({'content-type':'application/json; charset=utf-8','www-authenticate':'Basic realm="Foundly OS"'}));return res.end(JSON.stringify({error:'Authenticatie vereist',code:authConfigured()?'auth_invalid':'auth_not_configured'}))}if(u.pathname.startsWith('/api/')){const handled=await api(req,res,u);if(handled!==false)return;}if(u.pathname==='/index-script.js'&&req.method==='GET'){res.writeHead(200,baseHeaders({'content-type':'application/javascript; charset=utf-8'}));return fs.createReadStream(path.join(ROOT,'index-script.js')).pipe(res)}if(u.pathname==='/'||u.pathname==='/index.html'){if(!fs.existsSync(INDEX)){res.writeHead(500);return res.end('index.html ontbreekt');}res.writeHead(200,baseHeaders({'content-type':'text/html; charset=utf-8'}));return fs.createReadStream(INDEX).pipe(res);}res.writeHead(404,baseHeaders());res.end('Not found');}catch(err){console.error('[REQUEST ERROR]',String(err.message||err).replace(/[A-Za-z0-9_-]{24,}/g,'[redacted]').slice(0,240));json(res,500,{error:'Interne serverfout'});}});
server.listen(PORT,'0.0.0.0',()=>{console.log(`Foundly OS v${VERSION} ONLINE op poort ${PORT}`);const storage=storageStatus();if(!storage.configured_path||!storage.writable||env('NODE_ENV')==='production'&&!storage.separate_mount)console.warn('[PERSISTENCE WARNING] /data is niet als afzonderlijk schrijfbaar volume bewezen');const c=trustedContext();addEvent(c,'system',`Foundly OS v${VERSION} gestart`,{port:PORT,persistence:storage.writable});});
const workerMs=Math.max(60000,Number(cleanEnv('FOUNDLY_WORKER_INTERVAL_MS','300000'))||300000);setInterval(()=>workerTick(trustedContext()).catch(e=>console.error('[WORKER ERROR]',redactJarvisText(e.message,500))),workerMs).unref();
